import pytest

from bedrock_protocol import v924, v1001, v2168, v2225

versions = [v1001, v2168, v2225]

# generated by gophertunnel 0381a95:
# packet.ClientBoundDataDrivenUICloseAllScreens{}
CLOSE_ALL_SCREENS = bytes.fromhex("")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ClientBoundDataDrivenUICloseScreen{FormID: protocol.Option[uint32](300)}
CLOSE = bytes.fromhex("012c010000")

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ClientBoundDataDrivenUICloseScreen{}
ABSENT = bytes.fromhex("00")

GOLDENS = [
    pytest.param(
        v.ClientboundDataDrivenUICloseScreenPacket(form_id=300),
        CLOSE,
        id=f"{v.__name__.rpartition('.')[2]}-with-form-id",
    )
    for v in versions
] + [
    pytest.param(
        v.ClientboundDataDrivenUICloseScreenPacket(), ABSENT, id=f"{v.__name__.rpartition('.')[2]}-without-form-id"
    )
    for v in versions
]


def test_clientbound_data_driven_ui_close_all_screens_encodes_to_its_golden():
    assert bytes(v924.ClientboundDataDrivenUICloseAllScreensPacket()) == CLOSE_ALL_SCREENS


def test_clientbound_data_driven_ui_close_all_screens_decodes_from_its_golden():
    assert (
        v924.ClientboundDataDrivenUICloseAllScreensPacket.from_bytes(CLOSE_ALL_SCREENS)
        == v924.ClientboundDataDrivenUICloseAllScreensPacket()
    )


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_data_driven_ui_close_screen_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_data_driven_ui_close_screen_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", versions)
def test_clientbound_data_driven_ui_close_screen_rejects_a_truncated_form_id(version):
    with pytest.raises(ValueError, match="at byte"):
        version.ClientboundDataDrivenUICloseScreenPacket.from_bytes(bytes.fromhex("012c01"))
